import { useState, type FormEvent } from 'react';
import { useMutation, useQueryClient, type UseMutationResult } from '@tanstack/react-query';

async function postUser(name: string): Promise<{ id: string; name: string }> {
  const res = await fetch('/api/users', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

function AddUserForm() {
  const queryClient = useQueryClient();
  const [name, setName] = useState('');

  const mutation = useMutation({
    mutationFn: () => postUser(name),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
      setName('');
    },
  }) as UseMutationResult<
    { id: string; name: string },
    Error,
    void,
    unknown
  >;

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    mutation.mutate();
  };

  return (
    <form onSubmit={handleSubmit} className="user-form">
      <label htmlFor="name">Name</label>
      <input
        id="name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        disabled={mutation.isPending}
      />

      <button type="submit" disabled={mutation.isPending || !name.trim()}>
        {mutation.isPending ? 'Addingâ€¦' : 'Add User'}
      </button>

      {mutation.isSuccess && (
        <p role="status" className="success-msg">User added!</p>
      )}

      {mutation.isError && (
        <p role="alert" className="error-msg">
          Error: {mutation.error.message}
        </p>
      )}
    </form>
  );
}

function EditProfile({ userId, initialName }: { userId: string; initialName: string }) {
  const queryClient = useQueryClient();
  const [name, setName] = useState(initialName);

  const mutation = useMutation({
    mutationFn: async (newName: string) => {
      const res = await fetch(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newName }),
      });
      if (!res.ok) throw new Error(res.statusText);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
      mutation.reset(); // Return to idle so the form is reusable
    },
  });

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    mutation.mutate(name);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input value={name} onChange={(e) => setName(e.target.value)} disabled={mutation.isPending} />
      <button type="submit" disabled={mutation.isPending}>{mutation.isPending ? 'Savingâ€¦' : 'Save'}</button>
      {mutation.isSuccess && <p role="status">Profile saved!</p>}
      {mutation.isError && <p role="alert">{mutation.error.message}</p>}
    </form>
  );
}
